--   - Logger database schema for crm

-- Create logs table if it doesn't exist
CREATE TABLE IF NOT EXISTS crm_logs (
    id SERIAL PRIMARY KEY,
    timestamp TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    level TEXT NOT NULL,
    message TEXT NOT NULL,
    module_path TEXT,
    file_path TEXT,
    line_number INTEGER,
    additional_data JSONB
);

-- Create index on timestamp for faster queries
CREATE INDEX IF NOT EXISTS crm_logs_timestamp_idx ON crm_logs (timestamp);

-- Create index on level for filtering by log level
CREATE INDEX IF NOT EXISTS crm_logs_level_idx ON crm_logs (level);

-- Grant permissions to postgres user
GRANT ALL PRIVILEGES ON TABLE crm_logs TO postgres;
